import Tile from '../../../../../geometry/Tile.js';

// Why: the pass is not a search problem, and treating it as one is what produced a cage thirty tiles away reporting a crossing. Every obstacle in it is a scripted seam with a fixed stand and a fixed landing, both readable offline — the map gives the angles, the script gives the arithmetic — so the only question at runtime is which pocket the character is standing in. That has one answer, and it decides the action.
// Why: generated by `tools/nav/upass-areas.ts --emit` against `out/collision.lcnav.gz`. Re-derive it after a content change rather than editing it here.

/** A sealed pocket of the pass, named by the smallest packed tile in it. */
export interface UpassArea {
    area: string;
    /** The tile the walker routes to, to answer "am I in here". */
    anchor: Tile;
}

/** One crossing: stand on `stand`, send `op` at `loc`, arrive in `to` at `lands`. */
export interface UpassCrossing {
    from: string;
    to: string;
    loc: number;
    op: string;
    stand: Tile;
    lands: Tile;
}

